# ⭐⭐ La taille des chiffres. 16 pt EST LE MAXIMUM, ET IL A ÉTÉ MESURÉ.
# ⚠️⚠️ On a imprimé à 500 dpi la valeur la plus large de chaque plage,
#    dans chacune des douze perles, taille par taille, et compté les
#    pixels où le chiffre touche un trait de RANIHEI :
#       15,5 pt → aucun contact  ← INSTALLÉ
#       16   pt → 1 pixel, sur le « 24 » de la 2e fleur
#       17   pt → 1 pixel
#       18 pt → 35 pixels      19 pt → 255      20 pt → 602
#    ⚠️ SA DEUXIÈME MAQUETTE EST PLUS SERRÉE QUE LA PREMIÈRE : les perles
#    d'une même fleur s'y chevauchent davantage, et le carton est plus
#    étroit (81 mm au lieu de 85). Sur la première on tenait 20 pt.
#    NE PAS REMETTRE 20 SANS REFAIRE LA MESURE.
_T_PERLE = 15.5

# Le numéro de série, à la place EXACTE des « 001 » effacés.
# ⚠️ Sa ligne du bas se lit : [hibiscus] —— SÉRIE 001 —— [hibiscus].
#    Ses « 001 » font trois chiffres, les nôtres en font six : ils sont
#    donc calés à GAUCHE au départ de ses chiffres et s'étendent vers la
#    droite, dans l'espace que le filet décoratif occupe. Le filet est un
#    trait fin de la même couleur : le numéro se pose dessus comme sur
#    une ligne d'écriture, rien n'est effacé de son dessin.
SERIE_GAUCHE = 545.0     # bord gauche de ses chiffres (x 230 / 422)
SERIE_BASE = 995.8       # leur ligne de pied (y 477 / 479)
SERIE_PT = 34.8          # leur hauteur convertie en corps de police
SERIE_LARG = 0.34        # largeur maxi, en fraction du carton


