def _tracer_decor(c, larg, haut):
    """Repose le dessin de RANIHEI dans un rectangle larg x haut.
    ⚠️ UN SEUL remplissage pair-impair : les blancs intérieurs (le creux
    d'une perle, la nervure d'une feuille) se creusent tout seuls."""
    p = c.beginPath()
    for contour in _DECOR.split("|"):
        for t in contour.split(" "):
            v = [float(z) for z in t[1:].split(",")]
            xs = [v[i] / 1000.0 * larg for i in range(0, len(v), 2)]
            ys = [haut - v[i] / 1000.0 * haut for i in range(1, len(v), 2)]
            if t[0] == "M":
                p.moveTo(xs[0], ys[0])
            elif t[0] == "L":
                p.lineTo(xs[0], ys[0])
            else:
                p.curveTo(xs[0], ys[0], xs[1], ys[1], xs[2], ys[2])
        p.close()
    c.drawPath(p, stroke=0, fill=1)


def _forme_decor(c):
    """Gravé UNE SEULE FOIS par document, SANS COULEUR : un tampon qui ne
    choisit pas sa couleur prend celle posée au moment de l'utiliser.
    Un tampon pour les dix couleurs au lieu de dix.
    ⚠️ NE PAS REMETTRE setFillColor ICI."""
    nom = "BLOSSOM_DECOR"
    if not getattr(c, "_bp_forme_faite", False):
        c.beginForm(nom, lowerx=0, lowery=0, upperx=CARD_W, uppery=CARD_H)
        _tracer_decor(c, CARD_W, CARD_H)
        c.endForm()
        c._bp_forme_faite = True
    return nom


# ══ LA FEUILLE ═══════════════════════════════════════════════════════
# 6 cartons par feuille A4 portrait, 2 colonnes x 3 rangées — la planche
# que RANIHEI a fournie.
# ⚠️ SON CARTON EST PLUS HAUT QUE LARGE (452 x 488). C'est donc la
#    HAUTEUR de la feuille qui commande : trois rangées entrent tout
#    juste, et la largeur du carton en découle. Le bloc est ensuite
#    centré horizontalement — les marges latérales sont larges, c'est
#    normal, on ne peut pas faire autrement sans déformer son dessin.
PAGE_W, PAGE_H = A4
COLS_PAGE = 2
ROWS_PAGE = 3
MARGIN_Y = 6 * mm
GUTTER_Y = 4 * mm
GUTTER_X = 6 * mm
CARD_H = (PAGE_H - 2 * MARGIN_Y - (ROWS_PAGE - 1) * GUTTER_Y) / ROWS_PAGE
CARD_W = CARD_H * MAQ_W / MAQ_H          # le carton garde le format de la maquette
MARGIN_X = (PAGE_W - COLS_PAGE * CARD_W - GUTTER_X) / 2
BLOC_H = ROWS_PAGE * CARD_H + (ROWS_PAGE - 1) * GUTTER_Y

RAINBOW = [
    "#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
    "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41",
]
GRIS = colors.Color(0.42, 0.42, 0.42)
GRIS_CLAIR = colors.Color(0.80, 0.80, 0.80)


def _gen_carte(rng):
    """Trois numéros DIFFÉRENTS par groupe, tirés dans SA plage.
    Retourne la liste des 12 valeurs, groupe par groupe, dans l'ordre
    des perles tel qu'il est écrit dans GROUPES."""
    out = []
    for _nom, (a, b), perles in GROUPES:
        out.append(rng.sample(range(a, b + 1), len(perles)))
    return out


def _dessiner_carte(c, x0, y0, valeurs, couleur_hex, serie, style="eco",
                    evenement_id=""):
    police_ch, gris_ch = _style_chiffres(style)

    # 1) LE DESSIN DE RANIHEI, tel quel. La couleur se pose AVANT le tampon.
    _nom = _forme_decor(c)
    c.saveState()
    col = colors.HexColor(couleur_hex)
    c.setFillColor(col); c.setStrokeColor(col)
    c.translate(x0, y0)
    c.doForm(_nom)
    c.restoreState()

    if _sec:
        try:
            # ⚠️ 1,2 mm : c'est le retrait le moins mauvais, mesuré sur
            #    sept valeurs. Sur CE dessin il est IMPOSSIBLE de ne rien
            #    toucher — les feuilles et le titre vont jusqu'au bord du
            #    carton, il n'y a aucune bande libre. À 1,2 mm le cadre
            #    croise 7 pixels de feuillage à 500 dpi, soit un cheveu.
            #    C'est assumé : le microtexte est notre sécurité, et 7
            #    pixels ne se voient pas. Ne pas chercher mieux, j'ai
            #    essayé 0,8 · 1,6 · 2,0 · 2,4 · 3,0 · 3,6 mm.
            _sec.cadre_micro(c, x0, y0, CARD_W, CARD_H, serie, retrait=1.2 * mm)
        except Exception:
            pass

    # 2) LES DOUZE NUMÉROS — la seule chose qu'on ajoute.
    for (_nom_g, (a, b), perles), vals in zip(GROUPES, valeurs):
        # ⚠️ on mesure la valeur la plus large de CETTE plage, pas un
        #    « 88 » qui n'y apparaît jamais.
        _large = max(range(a, b + 1),
                     key=lambda v: pdfmetrics.stringWidth(str(v), police_ch, 20))
        for (px, py, pr), val in zip(perles, vals):
            cx = x0 + px / 1000.0 * CARD_W
            cy = y0 + CARD_H - py / 1000.0 * CARD_H
            r = pr / 1000.0 * CARD_W
            t = _T_PERLE
            # ⚠️ GARDE-FOU étalonné sur la mesure réelle (facteur 1,20),
            #    pas sur un cercle inscrit : voir le pavé de AHE, même
            #    histoire. Il ne sert qu'à rattraper un carton rapetissé.
            while t > 4:
                lg = pdfmetrics.stringWidth(str(_large), police_ch, t)
                ht = t * 0.72
                if ((lg / 2) ** 2 + (ht / 2) ** 2) ** 0.5 <= r * 1.22:
                    break
                t -= 0.5
            if _sec:
                _sec.chiffre_micro(c, val, cx, cy - t * 0.36, t, gris_ch,
                                   police_ch, epaisseur=_GRAS_TRAIT)
            else:
                c.setFillColor(gris_ch); c.setFont(police_ch, t)
                c.drawCentredString(cx, cy - t * 0.36, str(val))

    # 3) LE NUMÉRO DE SÉRIE, à la place des « 001 »
    c.setFillColor(colors.HexColor(couleur_hex))
    ts = SERIE_PT / 1000.0 * CARD_H
    _larg = CARD_W * SERIE_LARG
    while ts > 3 and pdfmetrics.stringWidth("%06d" % serie, POLICE, ts) > _larg:
        ts -= 0.25
    c.setFont(POLICE, ts)
    c.drawString(x0 + SERIE_GAUCHE / 1000.0 * CARD_W,
                 y0 + CARD_H - SERIE_BASE / 1000.0 * CARD_H,
                 "%06d" % serie)

    if _sec and evenement_id:
        try:
            _sec.carton_qr(c, x0 + CARD_W * 0.66, y0 + CARD_H * 0.03,
                           CARD_H * 0.13, evenement_id, serie)
        except Exception:
            pass


def generer_pdf(nb_cartes=6, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", style="eco", evenement_id="", page_start=1):
    """⚠️⚠️ RENVOIE UN BytesIO, PAS DES OCTETS."""
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)

    nb_cartes = max(1, min(int(nb_cartes), 10000))
    par_page = COLS_PAGE * ROWS_PAGE
    nb_pages = (nb_cartes + par_page - 1) // par_page

    rng = random.Random(620000 + int(serie_start))
    serie = int(serie_start)
    no_page = max(1, int(page_start))
    faites = 0

    for _ in range(nb_pages):
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 5.0)
        c.drawRightString(PAGE_W - 5 * mm, PAGE_H - 3.4 * mm, "%03d" % no_page)

        for rang in range(ROWS_PAGE):
            for col_i in range(COLS_PAGE):
                if faites >= nb_cartes:
                    break
                x0 = MARGIN_X + col_i * (CARD_W + GUTTER_X)
                y0 = MARGIN_Y + (ROWS_PAGE - 1 - rang) * (CARD_H + GUTTER_Y)
                vals = _gen_carte(rng)
                coul = (couleur_perso if (couleur and couleur_perso)
                        else RAINBOW[(serie - 1) % len(RAINBOW)] if couleur
                        else "#4A4A4A")
                _dessiner_carte(c, x0, y0, vals, coul, serie,
                                style=style, evenement_id=evenement_id)
                serie += 1
                faites += 1

        c.setStrokeColor(GRIS_CLAIR); c.setLineWidth(0.4); c.setDash(3, 3)
        xm = MARGIN_X + CARD_W + GUTTER_X / 2
        c.line(xm, MARGIN_Y - 2 * mm, xm, MARGIN_Y + BLOC_H + 2 * mm)
        for rang in range(1, ROWS_PAGE):
            ym = MARGIN_Y + rang * (CARD_H + GUTTER_Y) - GUTTER_Y / 2
            c.line(MARGIN_X - 2 * mm, ym, PAGE_W - MARGIN_X + 2 * mm, ym)
        c.setDash()

        c.showPage()
        no_page += 1

    c.save()
    buf.seek(0)
    return buf


def generer_couleur(**kw):
    kw["couleur"] = True
    return generer_pdf(**kw)


def generer_nb(**kw):
    kw["couleur"] = False
    return generer_pdf(**kw)


if __name__ == "__main__":
    pdf = generer_pdf(nb_cartes=6, couleur=True)
    with open("test_blossom.pdf", "wb") as f:
        f.write(pdf.read())
    print("BLOSSOM PEARL genere")
